import type { RequestInit } from "@/types";
import { handleFetchError, OperationPollingOptions, Result } from "@/types";

import {
  AccountInfoResponse,
  GetApiAccountQuotaHistoryParams,
  LoginRequest,
  LoginResponse,
  OperationDetailResponse,
  OperationFiltersResponseResponse,
  OperationListItemResponse,
  OTPDisableRequest,
  OTPGenerateResponse,
  OTPValidateRequest,
  OTPVerifyRequest,
  PasswordResetRequest,
  PasswordResetVerifyRequest,
  PongResponse,
  QuotaHistoryResponse,
  QuotaStatusResponse,
  RegisterRequest,
  ResendVerifyEmailRequest,
  UploadLimitResponse,
  VerifyEmailRequest,
} from "@/account/generated/accountAPI.schemas";
import type { OperationsListParams } from "@/query-utils";
import { buildOperationsQueryParams } from "@/query-utils";
import { delay, parseResponse, poll } from "@/http-utils";
import {
  buildApiUrl,
  buildJsonOptions,
  toAccountError,
} from "@/http/request";
import { AccountKeyIdentity } from "@/account/key-identity";

export {
  AccountKeyIdentity,
  KEY_TYPE_ETHEREUM,
  KEY_TYPE_SOLANA,
  WALLET_ALREADY_LINKED_MESSAGE,
} from "@/account/key-identity";
export type { KeyChallenge, KeyVerifyOutcome } from "@/account/key-identity";

const LOOPBACK_REGEX =
  /^localhost$|^(?:127(?:\.(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)){3}|\[::1\])$/;

/**
 * Operation status constants
 */
const OPERATION_STATUS = {
  COMPLETED: "completed",
  FAILED: "failed",
  ERROR: "error",
  PENDING: "pending",
  RUNNING: "running",
} as const;

/**
 * Default settled states for operations
 */
const DEFAULT_SETTLED_STATES = [
  OPERATION_STATUS.COMPLETED,
  OPERATION_STATUS.FAILED,
  OPERATION_STATUS.ERROR,
] as const;

type SettledState = typeof DEFAULT_SETTLED_STATES[number];

export { DEFAULT_SETTLED_STATES, OPERATION_STATUS, type SettledState };

export class AccountApi {
  /**
   * Key-identity login endpoints (wallet/passkey auth) — namespace object,
   * see @/account/key-identity.
   */
  public readonly keyIdentity: AccountKeyIdentity;

  private _jwtToken?: string;
  private readonly apiUrl: string;
  /** True when constructed against a localhost/loopback API (dev server). */
  private readonly isLocalDevHost: boolean;

  /**
   * Gets the current JWT token
   * @returns {string|undefined} The current JWT token or undefined if not set
   */
  private get jwtToken(): string | undefined {
    return this._jwtToken;
  }

  /**
   * Creates a new AccountApi instance
   * @param {string} apiUrl - The base API URL
   */
  constructor(apiUrl: string) {
    const apiUrlParsed = new URL(apiUrl);
    // Detect localhost/loopback construction before the host rewrite below:
    // dev servers keep /api/auth/key/* same-origin relative through the /api
    // proxy, and a rewritten account.<localhost> host does not exist there.
    this.isLocalDevHost = LOOPBACK_REGEX.test(apiUrlParsed.hostname);
    apiUrlParsed.hostname = `account.${apiUrlParsed.hostname}`;
    this.apiUrl = apiUrlParsed.toString();

    this.keyIdentity = new AccountKeyIdentity({
      apiUrl: () => this.apiUrl,
      sameOriginPaths: () => this.isLocalDevHost,
      token: () => this.jwtToken,
    });
  }

  /**
   * Clears the current JWT token
   */
  public clearToken(): void {
    this._jwtToken = undefined;
  }

  /**
   * Confirm a password reset
   * @param passwordResetVerifyRequest Password reset verification details
   * @returns Result indicating success or failure
   */
  public async confirmPasswordReset(
    passwordResetVerifyRequest: PasswordResetVerifyRequest,
  ): Promise<Result<void>> {
    return this.fetchJson<void>("/api/account/password-reset/confirm", {
      body: JSON.stringify(passwordResetVerifyRequest),
      method: "POST",
    });
  }

  /**
   * Disable OTP for two-factor authentication
   * @param otpDisableRequest OTP disable request details
   * @returns Result indicating success or failure
   */
  public async disableOtp(
    otpDisableRequest: OTPDisableRequest,
  ): Promise<Result<void>> {
    return this.fetchJson<void>("/api/auth/otp/disable", {
      body: JSON.stringify(otpDisableRequest),
      method: "POST",
    });
  }

  /**
   * Generate OTP for two-factor authentication
   * @returns Result containing OTP response
   */
  public async generateOtp(): Promise<Result<OTPGenerateResponse>> {
    return this.fetchJson<OTPGenerateResponse>("/api/auth/otp/generate", {
      method: "GET",
    });
  }

  /**
   * Get account information
   * @returns Result containing account info
   */
  public async info(): Promise<Result<AccountInfoResponse>> {
    return this.fetchJson<AccountInfoResponse>("/api/account", {
      method: "GET",
    });
  }

  public async quota(): Promise<Result<QuotaStatusResponse>> {
    return this.fetchJson<QuotaStatusResponse>("/api/account/quota", {
      method: "GET",
    });
  }

  public async quotaHistory(
    params?: GetApiAccountQuotaHistoryParams,
  ): Promise<Result<QuotaHistoryResponse>> {
    const url = new URL("/api/account/quota/history", this.apiUrl);

    if (params) {
      if (params.start_date) {
        url.searchParams.set("start_date", params.start_date);
      }
      if (params.end_date) {
        url.searchParams.set("end_date", params.end_date);
      }
      if (params.type) {
        url.searchParams.set("type", params.type);
      }
    }

    return this.fetchJson<QuotaHistoryResponse>(url.toString(), {
      method: "GET",
    });
  }

  /**
   * Login to the account service
   * @param loginRequest Login credentials
   * @returns Result containing login response or error
   */
  public async login(
    loginRequest: LoginRequest,
  ): Promise<Result<LoginResponse>> {
    const result = await this.fetchJson<LoginResponse>("/api/auth/login", {
      body: JSON.stringify(loginRequest),
      method: "POST",
    });

    if (result.success && result.data?.token) {
      this.setToken(result.data.token);
    }

    return result;
  }

  /**
   * Exchange an API key JWT for a login JWT.
   * The API key is sent as the raw Authorization header value (not Bearer).
   * @param apiKey API key JWT to exchange
   * @returns Result containing login response with the login JWT
   */
  public async loginWithApiKey(
    apiKey: string,
  ): Promise<Result<LoginResponse>> {
    const result = await this.fetchJson<LoginResponse>("/api/auth/key", {
      headers: { Authorization: `Bearer ${apiKey}` } as Record<string, string>,
      method: "POST",
    });

    if (result.success && result.data?.token) {
      this.setToken(result.data.token);
    }

    return result;
  }

  /**
   * Logout from the account service
   * @returns Result indicating success or failure
   */
  public async logout(): Promise<Result<void>> {
    const result = await this.fetchJson<void>("/api/auth/logout", {
      method: "POST",
    });

    if (result.success) {
      this.clearToken();
    }

    return result;
  }

  /**
   * Check authentication status
   * @returns Result containing ping response
   */
  public async ping(): Promise<Result<PongResponse>> {
    const result = await this.fetchJson<PongResponse>("/api/auth/ping", {
      method: "POST",
    });

    if (result.success && result.data?.token) {
      this.setToken(result.data.token);
    }

    return result;
  }

  /**
   * Register a new account
   * @param registerRequest Registration details
   * @returns Result indicating success or failure
   */
  public async register(
    registerRequest: RegisterRequest,
  ): Promise<Result<void>> {
    return this.fetchJson<void>("/api/auth/register", {
      body: JSON.stringify(registerRequest),
      method: "POST",
    });
  }

  /**
   * Request account deletion
   * @returns Result indicating success or failure
   */
  public async requestAccountDeletion(): Promise<Result<void>> {
    return this.fetchJson<void>("/api/account/delete", {
      method: "DELETE",
    });
  }

  /**
   * Request email verification to be resent
   * @param resendRequest Email details for verification
   * @returns Result indicating success or failure
   */
  public async requestEmailVerification(
    resendRequest: ResendVerifyEmailRequest,
  ): Promise<Result<void>> {
    return this.fetchJson<void>("/api/account/verify-email/resend", {
      body: JSON.stringify(resendRequest),
      method: "POST",
    });
  }

  /**
   * Request a password reset
   * @param passwordResetRequest Password reset request details
   * @returns Result indicating success or failure
   */
  public async requestPasswordReset(
    passwordResetRequest: PasswordResetRequest,
  ): Promise<Result<void>> {
    return this.fetchJson<void>("/api/account/password-reset/request", {
      body: JSON.stringify(passwordResetRequest),
      method: "POST",
    });
  }

  /**
   * Sets the JWT token for authentication
   * @param {string} token - The JWT token to set
   */
  public setToken(token: string): void {
    this._jwtToken = token;
  }

  /**
   * Update account email address
   * @param email New email address
   * @param password Current password for verification
   * @returns Result indicating success or failure
   */
  public async updateEmail(
    email: string,
    password: string,
  ): Promise<Result<void>> {
    return this.fetchJson<void>("/api/account/update-email", {
      body: JSON.stringify({ email, password }),
      method: "POST",
    });
  }

  /**
   * Update account password
   * @param currentPassword Current password for verification
   * @param newPassword New password to set
   * @returns Result indicating success or failure
   */
  public async updatePassword(
    currentPassword: string,
    newPassword: string,
  ): Promise<Result<void>> {
    return this.fetchJson<void>("/api/account/update-password", {
      body: JSON.stringify({
        current_password: currentPassword,
        new_password: newPassword,
      }),
      method: "POST",
    });
  }

  /**
   * Get upload limit information
   * @returns Result containing upload limit info
   */
  public async uploadLimit(): Promise<Result<UploadLimitResponse>> {
    return this.fetchJson<UploadLimitResponse>("/api/upload-limit", {
      method: "GET",
    });
  }

  /**
   * Validate OTP for two-factor authentication login
   * @param otpValidateRequest OTP validation details
   * @returns Result containing login response
   */
  public async validateOtp(
    otpValidateRequest: OTPValidateRequest,
  ): Promise<Result<LoginResponse>> {
    const result = await this.fetchJson<LoginResponse>(
      "/api/auth/otp/validate",
      {
        body: JSON.stringify(otpValidateRequest),
        method: "POST",
      },
    );

    if (result.success && result.data?.token) {
      this.setToken(result.data.token);
    }

    return result;
  }

  /**
   * Verify email address
   * @param verifyEmailRequest Email verification details
   * @param login Optional flag to enable auto-login after verification
   * @returns Result indicating success or failure
   */
  public async verifyEmail(
    verifyEmailRequest: VerifyEmailRequest,
    login?: boolean,
  ): Promise<Result<void>> {
    const url = new URL("/api/account/verify-email", this.apiUrl);
    if (login === true) {
      url.searchParams.set("login", "true");
    }
    return this.fetchJson<void>(url.toString(), {
      body: JSON.stringify(verifyEmailRequest),
      method: "POST",
    });
  }

  /**
   * Verify OTP for enabling two-factor authentication
   * @param otpVerifyRequest OTP verification details
   * @returns Result indicating success or failure
   */
  public async verifyOtp(
    otpVerifyRequest: OTPVerifyRequest,
  ): Promise<Result<void>> {
    return this.fetchJson<void>("/api/auth/otp/verify", {
      body: JSON.stringify(otpVerifyRequest),
      method: "POST",
    });
  }

  /**
   * List operations with filtering, searching, and pagination
   * 
   * @param params Query parameters using query-builder helpers
   * @returns Result containing list of operations
   * 
   * @example
   * ```ts
   * const result = await accountApi.listOperations({
   *   filters: [
   *     { field: "status", operator: "eq", value: "completed" },
   *     { field: "operation", operator: "in", value: ["upload", "download"] }
   *   ],
   *   sorters: [{ field: "id", order: "desc" }],
   *   pagination: { start: 0, end: 20, page: 1, pageSize: 20 },
   *   search: "myfile"
   * });
   * ```
   */
  public async listOperations(
    params?: OperationsListParams,
  ): Promise<Result<OperationListItemResponse>> {
    const url = new URL("/api/operations", this.apiUrl);
    
    if (params) {
      const searchParams = buildOperationsQueryParams(params);
      searchParams.forEach((value, key) => {
        url.searchParams.append(key, value);
      });
    }
    
    return this.fetchJson<OperationListItemResponse>(url.toString(), {
      method: "GET",
    });
  }

  /**
   * Get detailed information for a specific operation
   * @param id The operation ID
   * @returns Result containing operation details
   */
  public async getOperation(
    id: number,
  ): Promise<Result<OperationDetailResponse>> {
    return this.fetchJson<OperationDetailResponse>(`/api/operations/${id}`, {
      method: "GET",
    });
  }

  /**
   * Get available filter values for operations
   * @returns Result containing filter options
   */
  public async getOperationFilters(): Promise<Result<OperationFiltersResponseResponse>> {
    return this.fetchJson<OperationFiltersResponseResponse>("/api/operations/filters", {
      method: "GET",
    });
  }

  /**
   * Wait for an operation to complete or reach a settled state
   * @param id The operation ID to wait for
   * @param options Polling options (interval, timeout, settledStates)
   * @returns Result containing the final operation details
   */
  public async waitForOperation(
    id: number,
    options: OperationPollingOptions = {},
  ): Promise<Result<OperationDetailResponse>> {
    const {
      interval = 2000,
      timeout = 300000,
      settledStates = DEFAULT_SETTLED_STATES,
    } = options;

    const settledStatesSet = new Set(settledStates);

    return poll(
      () => this.getOperation(id),
      (operation) => {
        return !!(operation.status && settledStatesSet.has(operation.status.toLowerCase()));
      },
      { interval, timeout },
    );
  }

  /**
   * Makes a JSON request to the API
   * @template T
   * @param {string} input - The API endpoint path or absolute URL
   * @param {RequestInit} [init] - Optional request initialization
   * @returns {Promise<Result<T>>} Promise resolving to the result
   * @private
   */
  private async fetchJson<T>(
    input: string,
    init: RequestInit = {},
  ): Promise<Result<T>> {
    try {
      const response = await fetch(
        buildApiUrl(input, this.apiUrl),
        buildJsonOptions(init, this.jwtToken, "include"),
      );

      if (!response.ok) {
        return {
          error: await handleFetchError(response),
          success: false,
        };
      }

      const data = await parseResponse<T>(response);
      return {
        data,
        success: true,
      };
    } catch (e) {
      return {
        error: await toAccountError(e),
        success: false,
      };
    }
  }
}
